import { defineSlot } from '../Slot';
import type { Person } from '../../features/people/people';

/**
 * Extra cells on a person's row in the people table. A contribution renders one or more <td>s
 * (the slot is a Fragment inside the row's <tr>).
 */
export const PersonRow = defineSlot<{ sheetId: string; user: string; person: Person }>('person.row');
import { register } from './registry';
import type { Registered } from './registry';

// Discovery: every `features/**/*.slot.tsx` in the app is found here and registered, so there is
// no explicit list of features. A file exports `contribution`, or `contributions` for more than
// one. Imported once for its side effect by main.tsx.
const modules = import.meta.glob('../features/**/*.slot.tsx', { eager: true }) as Record<
  string,
  { contribution?: Omit<Registered, 'from' | 'order'> & { order?: number }; contributions?: Array<Omit<Registered, 'from' | 'order'> & { order?: number }> }
>;

for (const [from, mod] of Object.entries(modules)) {
  const declared = mod.contributions ?? (mod.contribution ? [mod.contribution] : []);
  for (const c of declared) {
    register({ ...c, from, order: c.order ?? 0 });
  }
}
import type { ComponentType } from 'react';

// The contribution store. It imports NOTHING — that is deliberate: discovery (slots/discover.ts)
// pulls in every feature's contribution file, and those files reach a slot definition, which
// reaches defineSlot, which reaches this file. Keeping the arrows one-way (discover -> features ->
// defs -> Slot -> registry) is what stops the module graph forming a cycle.

export type Registered = {
  slot: string;
  order: number;
  /** Source file — the React key and the deterministic tie-break for equal `order`. */
  from: string;
  Component: ComponentType<never>;
};

const contributions: Registered[] = [];

/** Called once per contribution at startup, by slots/discover.ts. */
export function register(entry: Registered): void {
  contributions.push(entry);
}

export function forSlot(id: string): Registered[] {
  return contributions
    .filter((c) => c.slot === id)
    .sort((a, b) => a.order - b.order || a.from.localeCompare(b.from));
}
import { useEffect, useState } from 'react';

// Every action on a person's row shows its refusal in the row's one person-error; taking any action on the
// row clears the error an earlier one left, so a row never shows a stale refusal next to a new one.
const clearers = new Map<string, Set<() => void>>();

/** This cell's error on the person's row, its setter, and `begin`: call it as an action on the row is taken
 *  to clear every error the row's cells show. */
export function usePersonError(sheetId: string, personId: number | string) {
  const key = `${sheetId}/${personId}`;
  const [error, setError] = useState('');
  useEffect(() => {
    const clear = () => setError('');
    const set = clearers.get(key) ?? new Set();
    set.add(clear);
    clearers.set(key, set);
    return () => {
      set.delete(clear);
      if (set.size === 0) clearers.delete(key);
    };
  }, [key]);
  const begin = () => clearers.get(key)?.forEach((clear) => clear());
  return { error, setError, begin };
}
import { useState } from 'react';
import type { FormEvent } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { HttpError, putJson } from '../../api/http';
import { useSubmitOnce } from '../../api/useSubmitOnce';
import { PersonRow } from '../../slots/defs/personRow';
import { useSheetToday } from '../sheet/sheet';
import { peopleKey } from './people';
import { usePersonError } from './rowError';
import type { Person } from './people';

/** Whether the person is retired and from when, and the form that retires them from a date (blank: the
 *  sheet's today). A claim dated after it is then refused; their claims keep counting in every total. */
function PersonRetire({ sheetId, user, person }: { sheetId: string; user: string; person: Person }) {
  const queryClient = useQueryClient();
  const today = useSheetToday(sheetId);
  const [from, setFrom] = useState('');
  const { error, setError, begin } = usePersonError(sheetId, person.id);
  const once = useSubmitOnce();

  const retire = useMutation({
    mutationFn: (body: { user: string; from: string }) =>
      putJson<Person>(`/api/sheets/${encodeURIComponent(sheetId)}/people/${person.id}/retire`, body),
    onSuccess: async () => {
      await queryClient.invalidateQueries({ queryKey: peopleKey(sheetId) });
      setFrom('');
    },
    onError: (e) =>
      setError(e instanceof HttpError && e.body ? e.body : `Could not retire ${person.name}: the date must be yyyy-mm-dd.`),
    onSettled: once.done,
  });

  const submit = (e: FormEvent) => {
    e.preventDefault();
    begin();
    if (!once.start()) return;
    retire.mutate({ user, from: from.trim() });
  };

  return (
    <td>
      Retired <span data-testid="person-retired">{person.retiredFrom !== null ? 'yes' : 'no'}</span>{' '}
      from <span data-testid="person-retired-from">{person.retiredFrom ?? ''}</span>{' '}
      <form onSubmit={submit} style={{ display: 'inline' }}>
        <input
          data-testid="person-retire-date"
          placeholder={today || 'yyyy-mm-dd'}
          value={from}
          onChange={(e) => {
            setFrom(e.target.value);
            setError('');
          }}
        />{' '}
        <button type="submit" data-testid="person-retire" disabled={retire.isPending}>
          Retire
        </button>
      </form>
      {error && (
        <p data-testid="person-error" role="alert">
          {error}
        </p>
      )}
    </td>
  );
}

export const contribution = PersonRow.fill({ order: 40, Component: PersonRetire });
